1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import type { User } from "@prisma/client";
6	import { db } from "./db";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
9	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
10	import { capacityCheck, diskCapacityCheck } from "./capacity";
11	import { invoiceCreateData } from "./invoices";
12	import { maybeRewardReferral } from "./actions-growth";
13	import { currentPromo, promoPriceCents } from "./promotions";
14	import { extraDiskPerGbCents } from "./disk-expand";
15	import {
16	  EXTRA_DISK_MAX_ADD_GB,
17	  EXTRA_DISK_MAX_TOTAL_GB,
18	  effectiveDiskGB,
19	  extraDiskCentsAt,
20	  extraDiskLabel,
21	  normalizeExtraDiskGB,
22	} from "./extra-disk";
23	
24	export class OrderError extends Error {}
25	
26	export const orderSchema = z.object({
27	  planId: z.string().min(1),
28	  osTemplateId: z.string().min(1),
29	  hostname: z
30	    .string()
31	    .min(3)
32	    .max(40)
33	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
34	  // Deploy-time extra-disk upsell. Coerced + step-normalized by
35	  // normalizeExtraDiskGB before it reaches here, so this is a range guard only.
36	  extraDiskGB: z.coerce.number().int().min(0).max(EXTRA_DISK_MAX_ADD_GB).optional(),
37	});
38	
39	export type OrderIntent = {
40	  planId: string;
41	  osTemplateId: string;
42	  hostname: string;
43	  nodeId?: string;
44	  addonMalware?: boolean;
45	  addonBackup?: boolean;
46	  addonDocker?: boolean;
47	  termMonths?: number;
48	  dedicatedIp?: boolean;
49	  sshPublicKey?: string;
50	  sshKeyName?: string;
51	  free?: boolean;
52	  /**
53	   * Extra root-disk GB bought at deploy time, ON TOP of the plan's diskGB. The VM
54	   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
55	   * post-deploy expansion job is needed. Permanent — never shrinks.
56	   */
57	  extraDiskGB?: number;
58	};
59	
60	/** Extract a plain OrderIntent from a deploy form. */
61	export function intentFromFormData(formData: FormData): OrderIntent {
62	  return {
63	    planId: String(formData.get("planId") ?? ""),
64	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
65	    hostname: String(formData.get("hostname") ?? ""),
66	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
67	    addonMalware: formData.get("addon_malware") === "1",
68	    addonBackup: formData.get("addon_backup") === "1",
69	    addonDocker: formData.get("addon_docker") === "1",
70	    termMonths: Number(formData.get("termMonths") ?? 1),
71	    dedicatedIp: formData.get("dedicatedIp") === "1",
72	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
73	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
74	    free: formData.get("free") === "1",
75	    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
76	    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
77	    // bought so it drops out of JSON.stringify: the intent is round-tripped
78	    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
79	    // createOrderCheckout), and every byte of headroom matters there.
80	    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
81	  };
82	}
83	
84	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
85	async function scheduleNode(planRamMB: number) {
86	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
87	  if (nodes.length === 0) return null;
88	  const loads = await Promise.all(
89	    nodes.map(async (n) => {
90	      const agg = await db.server.findMany({
91	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
92	        select: { plan: { select: { ramMB: true } } },
93	      });
94	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
95	      return { node: n, free: n.capacityRamMB - used };
96	    }),
97	  );
98	  loads.sort((a, b) => b.free - a.free);
99	  return loads[0].node;
100	}
101	
102	/** Validate + price an order without placing it. Throws OrderError on any problem. */
103	export async function orderQuote(intent: OrderIntent) {
104	  const parsed = orderSchema.safeParse(intent);
105	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
106	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
107	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
108	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
109	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
110	    throw new OrderError(
111	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
112	    );
113	  }
114	  const term = vpsTerm(Number(intent.termMonths ?? 1));
115	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
116	
117	  // Extra root disk, priced per GB/month and multiplied over the term exactly
118	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
119	  // promo — the customer pays the same $/GB whichever term they pick, and renews
120	  // at the same rate). Growth is one-way: this is permanent for the server.
121	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
122	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
123	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
124	  const extraDiskCents = extraDiskMonthlyCents * term.months;
125	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
126	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
127	  }
128	
129	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
130	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
131	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
132	  // real renewal price and this discounted value is the real first-term price.
133	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
134	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
135	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
136	  const promo = currentPromo(new Date());
137	  const planFirstTermCents = promoPriceCents(regularPlanCents, promo);
138	  const chargeCents = planFirstTermCents + ipCents + extraDiskCents;
139	  return {
140	    plan,
141	    os,
142	    term,
143	    chargeCents,
144	    promo,
145	    regularPlanCents,
146	    extraDiskGB,
147	    extraDiskMonthlyCents,
148	    extraDiskCents,
149	  };
150	}
151	
152	/**
153	 * Place an order: validate, charge the wallet (unless a free admin grant),
154	 * create the Server + PROVISION job. Returns the new server id. Does NOT
155	 * redirect. Callers must ensure funds exist (or pass free) — this still
156	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
157	 */
158	export async function placeOrder(user: User, intent: OrderIntent): Promise<string> {
159	  const { plan, os, term, chargeCents, promo, extraDiskGB, extraDiskMonthlyCents, extraDiskCents } =
160	    await orderQuote(intent);
161	  // Note the intro discount on the billing document (first term only; renews full).
