42	function sanitize(report: HealthReport): PublicHealth {
43	  const pub = (status: CompStatus): PublicComponent => ({ status, detail: PUBLIC_DETAIL[status] });
44	  return {
45	    web: pub(report.web.status),
46	    db: pub(report.db.status),
47	    worker: pub(report.worker.status),
48	    proxmox: pub(report.proxmox.status),
49	    checkedAt: report.checkedAt,
50	  };
51	}
