const guardKey = `register:${user.id}:${domain}`;
if (!beginSubmit(guardKey)) {
  return { error: "That registration is already being processed — give it a moment before retrying." };
}

try {
  const existing = await db.domain.findUnique({ where: { name: domain } });
  if (existing) {
    if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
    if (existing.status === "PENDING") {
      return { error: "You already have a registration in progress for this domain." };
    }
    return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
  }

  // Live availability + retail(markup) & cost prices from name.com
  let priceCents: number; // retail per year (customer)
  let costCents: number; // registrar cost per year (us)
  try {
    const [check] = await checkDomains([domain]);
    if (!check) return { error: "Could not check availability. Try again." };
    if (!check.available) return { error: "Domain is not available." };
    if (check.premium) return { error: "Premium domains are not supported yet." };
    if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
    priceCents = check.priceCents;
    costCents = check.costCents;
  } catch (e: any) {
    return { error: String(e?.message ?? e).slice(0, 200) };
  }

  const totalCents = domainTermPriceCents(priceCents, dTerm.years); // customer pays (retail, term-discounted)
  const registrarCostCents = costCents * dTerm.years; // we pay name.com the true cost
  if (user.balanceCents < totalCents) {
    return { error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.` };
  }

  let record;
  try {
    record = await db.$transaction(async (tx) => {
      // Re-check inside the transaction: the availability round-trip above is
      // slow enough for a second submit to slip in. `Domain.name` is UNIQUE, so
      // even if this read misses, the create below rolls the whole debit back.
      const dupe = await tx.domain.findUnique({ where: { name: domain }, select: { id: true } });
      if (dupe) throw new DuplicateDomainError();
      await debitWallet(tx, user.id, totalCents);
      await tx.walletTransaction.create({
        data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
      });
      return tx.domain.create({
        data: { name: domain, userId: user.id, priceCents, costCents, termYears: dTerm.years, status: "PENDING", registrar: "name.com" },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
      return { error: "This domain is already being registered — you have not been charged twice." };
    }
    throw e;
  }

  try {
    const { expiresAt } = await registerDomain(domain, dTerm.years, contactParsed.data as RegistrantContact, registrarCostCents);
    const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
    await db.domain.update({
      where: { id: record.id },
      data: {
        status: "ACTIVE",
        registeredAt: new Date(),
        expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
      },
    });
    await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
    await db.notification.create({
      data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
    });
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    // NEVER refund blind: a timeout/5xx often means the order DID go through.
    const verdict = await verifyRegistration(domain);

    if (verdict.state === "registered") {
